using System.Reflection;

namespace Invoicing;

/// <summary>Exports an invoice as a PDF byte stream.</summary>
public sealed class PdfExporter
{
    private static readonly Func<string, IEnumerable<string>, byte[]> RenderPdf = CreatePdfRenderer();

    public byte[] Export(Invoice invoice)
    {
        var lines = new List<string>();
        foreach (var line in invoice.Lines)
            lines.Add($"{line.Description}: {line.NetAmount}");
        // TODO: include the billing address block in the header
        return RenderPdf($"Invoice {invoice.Number}", lines);
    }

    private static Func<string, IEnumerable<string>, byte[]> CreatePdfRenderer()
    {
        const string rendererTypeName = "Invoicing.Legacy.RenderApiV1";
        var rendererType = typeof(Invoice).Assembly.GetType(rendererTypeName, throwOnError: true)!;
        var method = rendererType.GetMethod(
            "ToPdf",
            BindingFlags.Public | BindingFlags.Static,
            binder: null,
            types: new[] { typeof(string), typeof(IEnumerable<string>) },
            modifiers: null)
            ?? throw new MissingMethodException(rendererTypeName, "ToPdf");

        return method.CreateDelegate<Func<string, IEnumerable<string>, byte[]>>();
    }
}
